        return 5 + weight
    if kind == "fast":
        return 10 + 2 * weight
    raise ValueError("неизвестная доставка")

solution:
RATES = {
    "standard": lambda weight: 5 + weight,
    "fast": lambda weight: 10 + 2 * weight,
    "express": lambda weight: 20 + 3 * weight,
}


def shipping(kind, weight):
    if kind not in RATES:
        raise ValueError("неизвестная доставка")
    return RATES[kind](weight)

